async function _callScanRo(base64, mediaType = "image/jpeg", timeoutMs = 18000) {
  const sbInstance = window.__FR?.sb;
  const fnUrl = `${window.__SUPABASE_CONFIG__.url}/functions/v1/scan-ro`;

  const getToken = async () => {
    // Always refresh to ensure a non-expired token
    const refreshed = await sbInstance.auth.refreshSession().catch(() => null);
    const session = refreshed?.data?.session || (await sbInstance.auth.getSession()).data?.session;
    return session?.access_token || null;
  };

  const token = await getToken();
  if (!token) throw new Error("auth_expired");

  const doFetch = async (tok) => {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeoutMs);
    try {
      const res = await fetch(fnUrl, {
        method: "POST",
        signal: ctrl.signal,
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${tok}`,
          "apikey": window.__SUPABASE_CONFIG__.anonKey,
        },
        body: JSON.stringify({ imageBase64: base64, mediaType }),
      });
      if (!res.ok) {
        const txt = await res.text().catch(() => String(res.status));
        throw Object.assign(new Error(`Scan failed (${res.status}): ${txt}`), { status: res.status });
      }
      return res.json();
    } catch (e) {
      if (e.name === "AbortError") throw new Error("OCR timed out — try again");
      throw e;
    } finally {
      clearTimeout(timer);
    }
  };

  try {
    return await doFetch(token);
  } catch (e) {
    // On 401, refresh once more and retry
    if (e.status === 401) {
      const fresh = await getToken();
      if (fresh && fresh !== token) return await doFetch(fresh);
    }
    throw e;
  }
}

// Snap-to-fill: scan photo immediately when selected, prefill form fields before save.
async function scanPhotoAndPrefillForm(file) {
  if (!file) return;

  const scanStatus = document.getElementById("photoScanStatus");
  const refEl      = document.getElementById("ref");
  const vinEl      = document.getElementById("vin8");
  const typeEl     = document.getElementById("typeText");
  const detailsPanel = document.getElementById("detailsPanel");
  const detailsBtn   = document.getElementById("toggleDetailsBtn");

  const showStatus = (msg, isScanning = false) => {
    if (!scanStatus) return;
    scanStatus.textContent = msg;
    scanStatus.style.display = msg ? "" : "none";
    scanStatus.className = "fr26ScanStatus" + (isScanning ? " scanning" : "");
  };

  showStatus("Reading photo…", true);

  try {
    const dataUrl  = await compressImageFileToDataUrl(file, 800, 0.80);
    const base64   = dataUrl.split(",")[1];
    const mediaType = dataUrl.match(/data:([^;]+)/)?.[1] || "image/jpeg";
    const result   = await _callScanRo(base64, mediaType);

    const { ro, vin, stk, job } = result || {};
    const filled = [];

    // Fill RO/Stock — prefer RO when both exist (Repair Order form)
    if (refEl && !refEl.value.trim()) {
      if (ro) {
        // RO form: combine RO/STK if both present (e.g. "474073/A7001")
        refEl.value = stk ? `${ro}/${stk}` : ro;
        document.getElementById("refTypeRO")?.click();
        filled.push(stk ? `RO ${ro}/STK ${stk}` : `RO ${ro}`);
      } else if (stk) {
        // Get Ready form: fill stock, set toggle to Stock
        refEl.value = stk;
        document.getElementById("refTypeSTK")?.click();
        filled.push(`STK ${stk}`);
      }
    }

    // Fill VIN (last 8) only if field is empty
    if (vinEl && !vinEl.value.trim() && vin) {
      const vin8 = vin.replace(/[^A-Za-z0-9]/g, "").slice(-8).toUpperCase();
      if (vin8.length >= 6) {
        vinEl.value = vin8;
        filled.push(`VIN …${vin8}`);
      }
    }

    // Auto-fill Work Done if empty and job was detected
    if (typeEl && !typeEl.value.trim() && job) {
      typeEl.value = job;
      filled.push(`Job: ${job}`);
    }

    if (filled.length) {
      // Open the details panel so user can see what was filled
      if (detailsPanel && detailsPanel.style.display === "none") {
        detailsPanel.style.display = "block";
        if (detailsBtn) detailsBtn.textContent = "Less";
      }
      showStatus("✓ " + filled.join("  ·  "));
      // If work done was auto-filled, focus hours; otherwise focus work done
      setTimeout(() => {
        if (job && typeEl?.value) {
          document.getElementById("hours")?.focus();
        } else {
          typeEl?.focus();
        }
      }, 80);
    } else {
      showStatus("No RO, STK or VIN found — fill in manually");
      setTimeout(() => showStatus(""), 3500);
    }

    setPhotoSummaryState("Selected");

  } catch (e) {
    setPhotoSummaryState("Selected");
    const msg = e?.message || "";
    console.warn("[OCR prefill error]", msg, e);
    if (msg === "auth_expired" || e?.status === 401) {
      showStatus("Sign in on More page to enable OCR");
      setTimeout(() => showStatus(""), 4000);
      return;
    }
    if (msg.includes("timed out")) {
      showStatus("Scan timed out — fill in manually");
      setTimeout(() => showStatus(""), 3500);
      return;
    }
    showStatus(`Scan failed: ${msg.slice(0, 50) || "unknown error"}`);
    setTimeout(() => showStatus(""), 5000);
  }
}

async function autoScanPhotoAndPatch(file, entryId, currentRef, currentVin8) {
  try {
    const dataUrl = await compressImageFileToDataUrl(file, 1200, 0.75);
    const base64 = dataUrl.split(",")[1];
    const mediaType = dataUrl.match(/data:([^;]+)/)?.[1] || "image/jpeg";
    const { ro, vin, stk } = await _callScanRo(base64, mediaType);

    const patch = {};
    const found = [];

    const hasRef = !!String(currentRef || "").trim();
    if (!hasRef) {
      if (ro)       { patch.ro_number = ro;  found.push(`RO: ${ro}`);   }
      else if (stk) { patch.ro_number = stk; found.push(`STK: ${stk}`); }
    }

    const hasVin = !!String(currentVin8 || "").trim();
    if (!hasVin && vin) {
      const vin8 = vin.replace(/[^A-Za-z0-9]/g, "").slice(-8).toUpperCase();
      if (vin8.length >= 6) { patch.vin8 = vin8; found.push(`VIN: ${vin8}`); }
    }

    if (!Object.keys(patch).length) return;

    const sbInstance = window.__FR?.sb;
    const uid = window.CURRENT_UID;
    if (sbInstance && entryId && uid) {
      await sbInstance.from("work_logs").update(patch).eq("id", entryId).eq("user_id", uid);
    }

    if (Array.isArray(window.CURRENT_ENTRIES)) {
      const idx = window.CURRENT_ENTRIES.findIndex(e => String(e.id) === String(entryId));
      if (idx >= 0) {
        const updated = { ...window.CURRENT_ENTRIES[idx] };
        if (patch.ro_number) {
          updated.ro_number = patch.ro_number;
          updated.ref = patch.ro_number;
          updated.ro  = patch.ro_number;
        }
        if (patch.vin8) updated.vin8 = patch.vin8;
        window.CURRENT_ENTRIES[idx] = updated;
        refreshUI?.(window.CURRENT_ENTRIES);
      }
    }

    if (found.length) toast(`Photo scanned — ${found.join(" · ")}`);
  } catch (e) {
    console.warn("[OCR]", e?.message || e);
    const msg = e?.message || "";
    // Auth/session errors are silent — user didn't ask for OCR explicitly
    if (msg === "auth_expired" || e?.status === 401 || /unauthorized/i.test(msg)) return;
    if (msg.includes("timed out")) { toast("Photo scan timed out — tap again to retry"); return; }
    // Other errors: brief console note only, not a user-facing toast
  }
}

let EDITING_ID = null; // null = creating new
let EDITING_ENTRY = null;
let isSaving = false;

/* ── Form draft (survives accidental refresh) ── */
const LS_DRAFT = "fr_form_draft";
let _draftTimer = null;

function saveDraft() {
  if (EDITING_ID) return;
  const draft = {
    hours: document.getElementById("hours")?.value || "",
    typeText: document.getElementById("typeText")?.value || "",
    ref: document.getElementById("ref")?.value || "",
    vin8: document.getElementById("vin8")?.value || "",
    rate: document.querySelector('input[name="rate"]')?.value || "",
    notes: document.querySelector('textarea[name="notes"]')?.value || "",
    isComeback: !!(document.getElementById("isComeback")?.checked),
    refType: currentRefType,
    detailsOpen: document.getElementById("detailsPanel")?.style.display !== "none",
    savedAt: Date.now(),
  };
  if (!draft.hours && !draft.typeText) { localStorage.removeItem(LS_DRAFT); return; }
  try { localStorage.setItem(LS_DRAFT, JSON.stringify(draft)); } catch {}
}

function debouncedSaveDraft() {
  clearTimeout(_draftTimer);
  _draftTimer = setTimeout(saveDraft, 400);
}

function restoreDraft() {
  if (EDITING_ID) return;
  try {
    const raw = localStorage.getItem(LS_DRAFT);
    if (!raw) return;
    const draft = JSON.parse(raw);
    if (!draft || (!draft.hours && !draft.typeText)) return;

    // Only restore transient fields (hours, type) within a 15-min window.
    // After that, the user has moved on — starting fresh is less surprising.
    const ageMs = Date.now() - (draft.savedAt || 0);
    const fresh = ageMs < 15 * 60 * 1000;
    if (!fresh) {
      localStorage.removeItem(LS_DRAFT);
      return;
    }

    const hoursEl = document.getElementById("hours");
    const typeEl  = document.getElementById("typeText");
    const refEl   = document.getElementById("ref");
    const vinEl   = document.getElementById("vin8");
    const rateEl  = document.querySelector('input[name="rate"]');
    const notesEl = document.querySelector('textarea[name="notes"]');
    const cbEl    = document.getElementById("isComeback");

    if (draft.hours   && hoursEl) { hoursEl.value = draft.hours; hoursEl.dataset.touched = "1"; }
    if (draft.typeText && typeEl) typeEl.value = draft.typeText;
    if (draft.rate    && rateEl)  { rateEl.value = draft.rate; rateEl.dataset.touched = "1"; }
    if (draft.notes   && notesEl) notesEl.value = draft.notes;
    if (cbEl) cbEl.checked = !!draft.isComeback;
    if (draft.refType) setRefType(draft.refType);

    const hasDetails = draft.ref || draft.vin8 || draft.detailsOpen;
    if (hasDetails) {
      if (draft.ref && refEl) refEl.value = draft.ref;
      if (draft.vin8 && vinEl) vinEl.value = draft.vin8;
      const dp  = document.getElementById("detailsPanel");
      const dbt = document.getElementById("toggleDetailsBtn");
      if (dp)  dp.style.display  = "block";
      if (dbt) dbt.textContent   = "Less";
    }

    updateEarningsPreview?.();
    // Trigger listeners so updateSaveEnabled re-evaluates the restored values
    ["hours", "typeText"].forEach(id =>
      document.getElementById(id)?.dispatchEvent(new Event("input", { bubbles: true }))
    );
    // silent restore — user can see their content was carried over
  } catch {}
}

function clearDraft() {
  clearTimeout(_draftTimer);
  localStorage.removeItem(LS_DRAFT);
}
const LS_KEEP_LAST_WORK = "fr_keep_last_work";
const LS_LAST_WORK_TYPE = "fr_last_work_type";

function shouldKeepLastWork() {
  return localStorage.getItem(LS_KEEP_LAST_WORK) !== "0";
}

function setKeepLastWork(enabled) {
  localStorage.setItem(LS_KEEP_LAST_WORK, enabled ? "1" : "0");
}

function syncKeepLastWorkInput() {
  const keepLastWorkEl = document.getElementById("keepLastWork");
  if (keepLastWorkEl) keepLastWorkEl.checked = shouldKeepLastWork();
}

function getLastWorkType() {
  return String(localStorage.getItem(LS_LAST_WORK_TYPE) || "").trim();
}

function rememberLastWorkType(typeName) {
  const next = String(typeName || "").trim();
  if (!next) return;
  localStorage.setItem(LS_LAST_WORK_TYPE, next);
}

function restoreLastWorkType({ force = false } = {}) {
  if (!shouldKeepLastWork() || EDITING_ID) return;
  const typeEl = document.getElementById("typeText");
  if (!typeEl) return;
  if (!force && String(typeEl.value || "").trim()) return;
  const lastType = getLastWorkType();
  if (!lastType) return;
  typeEl.value = lastType;
}

function setQuickHoursValue(value) {
  const hoursEl = document.getElementById("hours");
  if (!hoursEl) return;
  const next = String(value || "").trim();
  if (!(num(next) > 0)) return;
  hoursEl.value = next;
  hoursEl.dataset.touched = "1";
  hoursEl.dispatchEvent(new Event("input", { bubbles: true }));
  hoursEl.dispatchEvent(new Event("change", { bubbles: true }));
  document.querySelectorAll("[data-hours-quick]").forEach((btn) => {
    btn.classList.toggle("selected", btn.getAttribute("data-hours-quick") === next);
  });
}

